  \uses{thm:biPath_has_vjp, ax:pdiv_add, def:hasvjpmat}
  Rank-2 transcription of Theorem~\ref{thm:biPath_has_vjp}: given
  \(\HasVJPMat\) for \(F\) and \(G\) (with flat differentiability),
  \(\HasVJPMat\, (F + G)\) with backward
  \(B_F(A, dY) + B_G(A, dY)\).
\end{theorem}

n30344.content:
\begin{proof}
\leanok
